// Vendored byte for byte from Al-Ummah-Now/AlUmmahNow packages/fanous-tokens/errors/aun-error-page.css (the
// error-page family's card, wiki guides/error-pages.md). Do not edit: change the monorepo's sheet and copy it here.
export const ERROR_PAGE_CSS = "/* The error card (Al Ummah Now error-page family, wiki guides/error-pages.md): 404, 410, 500, a\n   crashed page, sign-in failed. One solid card with a golden edge and glow on the lantern street,\n   the same colour on every app (owner, 2026-11-22: the street never shows through a card). Used as is by the videos site and admin; www, scholar sites, the dev site,\n   Auth and the CMS vendor it byte for byte (never edit a vendored copy). The buttons are the family's\n   own too (.ep-btn-primary / .ep-btn-secondary): no app's button classes go on the card, so the gold,\n   height, shape and type are the same everywhere.\n   --fanous-* tokens only; the edge and glow read the Surfaces primitive's --aun-glass-* tokens when the\n   app has them (packages/fanous-tokens/surfaces). Logical properties (one sheet for en and ar), no\n   animation, no blur. */\n/* The card: the videos site's card colour, worked out here from the page colour so every app gets the\n   same one whatever its mode selector is (.dark, data-mode, prefers-color-scheme): a dark page lifted\n   11.9% toward white (the glass base, 14% white, blended 85% over the page), a light page 80% white.\n   The page's luminance picks between them. A browser without relative colours gets the theme surface,\n   also solid. A gold edge and a soft gold glow at rest. */\n.ep{--ep-c:var(--fanous-color-primary,#e8b477);\n  --ep-surface:var(--fanous-color-surface);\n  --ep-edge:var(--aun-glass-edge,color-mix(in srgb,var(--ep-c) 55%,var(--fanous-color-surface)));\n  --ep-glow:var(--aun-glass-glow,0 0 28px -4px color-mix(in srgb,var(--ep-c) 45%,transparent));\n  --ep-tint:color-mix(in srgb,var(--fanous-color-text-primary) 7%,transparent);\n  display:grid;grid-template-columns:minmax(0,1fr);place-items:center;box-sizing:border-box;width:100%;max-width:100%;overflow-x:clip;min-height:calc(100dvh - 160px);padding:clamp(24px,6vw,72px) 16px;color:var(--fanous-color-text-primary)}\n@supports (color:rgb(from red r g b)){.ep{--ep-surface:rgb(from var(--fanous-color-background) calc(r + (255 - r) * (0.119 + 0.681 * clamp(0, (0.2126 * r + 0.7152 * g + 0.0722 * b - 127.5) * 10, 1))) calc(g + (255 - g) * (0.119 + 0.681 * clamp(0, (0.2126 * r + 0.7152 * g + 0.0722 * b - 127.5) * 10, 1))) calc(b + (255 - b) * (0.119 + 0.681 * clamp(0, (0.2126 * r + 0.7152 * g + 0.0722 * b - 127.5) * 10, 1))))}}\n.ep-card{box-sizing:border-box;width:100%;max-width:640px;min-width:0;overflow-wrap:anywhere;border:1px solid var(--ep-edge);border-radius:var(--aun-radius-card,16px);background:var(--ep-surface);box-shadow:var(--ep-glow);padding:clamp(24px,4vw,40px);text-align:start}\n@media print{.ep-card{background:none;box-shadow:none}}\n.ep-head{display:grid;grid-template-columns:auto 1fr;column-gap:var(--fanous-spacing-md,12px);align-items:center}\n.ep-badge{display:grid;place-items:center;width:52px;height:52px;border-radius:14px;background:var(--fanous-color-primary);color:var(--fanous-color-on-primary);box-shadow:0 0 18px -4px color-mix(in srgb,var(--ep-c) 60%,transparent)}\n.ep-badge svg{width:26px;height:26px}\n.ep-heading,.ep-head,.ep-search,.ep-foot,.ep-actions{min-width:0}\n.ep-code{margin:0 0 2px;font-size:13px;font-weight:600;letter-spacing:.06em;color:var(--fanous-color-text-secondary)}\nhtml[lang=ar] .ep-code,.ep[lang=ar] .ep-code{letter-spacing:0}\n.ep-title{margin:0;font-family:inherit;font-size:clamp(24px,3vw,30px);font-weight:700;line-height:1.25;letter-spacing:normal;text-wrap:balance;color:var(--fanous-color-text-primary)}\n.ep[lang=ar] .ep-title{line-height:1.45}\n/* Balanced lines: a two- or three-line body never ends on one lone word */\n.ep-body{grid-column:1/-1;margin:var(--fanous-spacing-md,12px) 0 0;max-width:60ch;font-size:17px;line-height:1.65;text-wrap:balance;color:var(--fanous-color-text-secondary)}\n.ep[lang=ar] .ep-body{line-height:1.9}\n.ep-s{display:inline-block}\n\n.ep-search{display:flex;gap:var(--fanous-spacing-sm,8px);margin-block-start:var(--fanous-spacing-xl,24px)}\n.ep-search-input{flex:1 1 0;inline-size:100%;min-inline-size:0;box-sizing:border-box;min-height:44px;padding:0 14px;border:1px solid var(--fanous-color-outline);border-radius:12px;background:var(--fanous-color-surface);color:var(--fanous-color-text-primary);font:inherit;font-size:16px}\n.ep-search-input::placeholder{color:var(--fanous-color-text-secondary);opacity:1}\n.ep-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}\n/* The family's buttons (UNIFY): a 44px pill with the page's own font; the main action filled with the\n   theme's button colour, the others outlined. Links and <button>s look the same. */\n.ep .ep-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;box-sizing:border-box;min-height:44px;margin:0;padding:0 20px;border-radius:999px;font-family:inherit;font-size:15px;font-weight:600;line-height:1.25;letter-spacing:normal;text-decoration:none;text-transform:none;white-space:nowrap;cursor:pointer}\n.ep .ep-btn-primary{background:var(--fanous-c-button-primary-bg,var(--fanous-color-primary));color:var(--fanous-c-button-primary-text,var(--fanous-color-on-primary));border:1px solid transparent;box-shadow:none}\n.ep .ep-btn-secondary{background:transparent;color:var(--fanous-color-text-primary);border:1px solid var(--fanous-c-button-secondary-border,var(--fanous-color-outline));box-shadow:none}\n@media(hover:hover){.ep .ep-btn-primary:hover{background:var(--fanous-c-button-primary-hover,var(--fanous-c-button-primary-bg,var(--fanous-color-primary)))}.ep .ep-btn-secondary:hover{background:var(--ep-tint)}}\n.ep .ep-btn[hidden]{display:none}\n.ep-btn svg{width:18px;height:18px;flex:none}\n.ep[dir=rtl] svg:is([data-icon=back],[data-icon=session]){transform:scaleX(-1)}\n\n.ep-ref{margin-block-start:var(--fanous-spacing-xl,24px);padding:12px 16px;border-radius:10px;background:var(--ep-tint);font-size:14px}\n.ep-ref-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px}\n.ep-ref-label{color:var(--fanous-color-text-secondary)}\n.ep-ref-code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-weight:600;letter-spacing:.02em;color:var(--fanous-color-text-primary)}\n/* The link colour pulled 30% toward the text colour: on the tinted reference box a plain link colour fell under 4.5:1 (Zujaj dark 4.46:1) */\n.ep-ref-copy{display:inline-flex;align-items:center;gap:6px;margin-inline-start:auto;min-height:36px;padding-inline:10px;border:0;border-radius:999px;background:transparent;color:color-mix(in srgb,var(--fanous-color-link) 70%,var(--fanous-color-text-primary));font:inherit;font-weight:600;cursor:pointer}\n.ep-ref-copy svg{width:16px;height:16px}\n@media(hover:hover){.ep-ref-copy:hover{background:var(--ep-tint)}}\n.ep-ref-hint{margin:6px 0 0;color:var(--fanous-color-text-secondary);line-height:1.5;text-wrap:balance}\n\n/* Footer: help on the start side, the actions at the end edge (main action last, filled), on one row\n   in every language. The card is 640px so the Arabic help line stays on one line beside the widest\n   pair (« حاول مرة أخرى » + « الصفحة الرئيسية »); a narrower window wraps it in its own column, balanced */\n.ep-foot{display:flex;flex-wrap:nowrap;align-items:center;justify-content:space-between;gap:var(--fanous-spacing-md,12px);margin-block-start:var(--fanous-spacing-xl,24px);padding-block-start:var(--fanous-spacing-lg,16px);border-block-start:1px solid var(--fanous-color-divider)}\n.ep-help{flex:1 1 0;min-width:0;margin:0;font-size:14px;line-height:1.5;text-wrap:balance;color:var(--fanous-color-text-secondary)}\n.ep-help a{color:var(--fanous-color-link);font-weight:600;text-decoration:underline;text-underline-offset:2px;white-space:nowrap}\n.ep-actions{display:flex;flex:none;flex-wrap:nowrap;gap:var(--fanous-spacing-sm,8px);margin-inline-start:auto}\n.ep :focus-visible{outline:2px solid var(--fanous-color-focus-ring);outline-offset:2px}\n\n@media(max-width:520px){\n  .ep{place-items:start center;min-height:0;padding-block-start:24px}\n  .ep-search{flex-direction:column}\n  .ep-search-btn{justify-content:center}\n  .ep-foot{flex-direction:column-reverse;align-items:stretch}\n  .ep-help{flex:none}\n  .ep-actions{flex-direction:column-reverse;margin-inline-start:0}\n  .ep-actions .ep-btn{width:100%}\n  /* The reference on one line and Copy on the next, starting under the label (its icon on the label's\n     edge): wrapped by flex, Copy floated alone at the end edge, far from what it copies */\n  .ep-ref-row{display:grid;grid-template-columns:auto minmax(0,1fr);column-gap:8px;row-gap:2px}\n  .ep-ref-code{overflow-wrap:anywhere}\n  .ep-ref-copy{grid-column:1/-1;justify-self:start;margin-inline:-10px 0}\n}\n";
